/* Humana — theme inspire des guidelines Cegid */

:root,
[data-theme="light"] {
  color-scheme: light;

  /* Palette inspiree Cegid */
  --forest: #022341;
  --forest-mid: #0046fe;
  --forest-deep: #011a33;
  --lime: #cfe0ff;
  --lime-hover: #bed4ff;
  --lime-muted: #edf3ff;

  --bg: #f5f7fb;
  --surface: #ffffff;
  --surface-2: #f7f7f7;
  --surface-hover: #f0f0f0;
  --border: #e0e0e0;
  --border-strong: #cccccc;

  --text: #0f172a;
  --text-secondary: #475569;
  --text-tertiary: #64748b;

  --success-bg: #e8f7ef;
  --success-text: #1f7a46;
  --warning-bg: #fff7e8;
  --warning-text: #8a5b12;
  --error-text: #b42318;
  --error-bg: #fef3f2;

  --sidebar-width: 240px;
  --header-height: 60px;
  --sidebar-bg: var(--forest);
  --sidebar-border: rgba(255, 255, 255, 0.08);
  --sidebar-text: rgba(255, 255, 255, 0.72);
  --sidebar-text-active: #ffffff;
  --sidebar-hover: rgba(255, 255, 255, 0.06);
  --sidebar-active: var(--forest-mid);
  --sidebar-indicator: var(--lime);

  --topbar-bg: #ffffff;
  --login-bg: var(--bg);
  --login-brand-bg: var(--forest);
  --login-panel-bg: #ffffff;
  --table-head: #f7f7f7;
  --backdrop: rgba(2, 35, 65, 0.55);
  --input-bg: #ffffff;

  --radius: 10px;
  --radius-lg: 16px;
  --radius-pill: 999px;

  --s1: 4px;
  --s2: 8px;
  --s3: 12px;
  --s4: 16px;
  --s5: 24px;
  --s6: 32px;
  --s7: 48px;
  --transition: 150ms ease;
  --font: "Poppins", "Segoe UI", system-ui, sans-serif;
  --bg-image-login: url('data:image/png;base64,');
  --bg-image-main: url('data:image/png;base64,');
  --bg-image-card: url('data:image/png;base64,');
  --bg-image-alt-1: url('data:image/png;base64,');
  --bg-image-alt-2: url('data:image/png;base64,');
  --bg-image-alt-3: url('data:image/png;base64,');

  --accent: var(--forest-mid);
  --accent-hover: var(--forest-deep);
  --accent-muted: var(--lime-muted);
  --accent-subtle: var(--lime-muted);
  --brand: var(--forest-mid);
  --brand-dark: var(--forest-deep);
  --brand-soft: var(--lime-muted);
  --brand-glow: rgba(0, 70, 254, 0.18);
  --ink: var(--text);
  --ink-secondary: var(--text-secondary);
  --muted: var(--text-tertiary);
  --line: var(--border);
  --line-strong: var(--border-strong);
  --canvas: var(--bg);
  --heading: var(--text);
  --radius-sm: var(--radius);

  font-family: var(--font);
  color: var(--text);
  background: var(--bg);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

[data-theme="dark"] {
  color-scheme: dark;

  --forest: #01162c;
  --forest-mid: #3b7bff;
  --forest-deep: #001021;
  --lime: #9ebeff;
  --lime-hover: #8cb0ff;
  --lime-muted: #152948;

  --bg: #0b1220;
  --surface: #121c2f;
  --surface-2: #1a2740;
  --surface-hover: #22324f;
  --border: #2a3c5e;
  --border-strong: #36507c;

  --text: #e6eefc;
  --text-secondary: #b8c8e4;
  --text-tertiary: #8ea2c6;

  --success-bg: #123326;
  --success-text: #78d9a2;
  --warning-bg: #332612;
  --warning-text: #f0c060;
  --error-text: #f87171;
  --error-bg: #331818;

  --sidebar-bg: #07172c;
  --sidebar-border: rgba(255, 255, 255, 0.06);
  --sidebar-text: rgba(255, 255, 255, 0.65);
  --sidebar-active: var(--forest-mid);
  --topbar-bg: var(--surface);
  --login-brand-bg: var(--forest);
  --login-panel-bg: var(--surface);
  --table-head: var(--surface-2);
  --backdrop: rgba(0, 0, 0, 0.65);
  --input-bg: var(--surface-2);
  --brand-glow: rgba(59, 123, 255, 0.2);
}

*, *::before, *::after { box-sizing: border-box; }

html, body { min-width: 320px; min-height: 100%; margin: 0; }

:root {
  --logo-image: url("data:image/jpeg;base64,");
  --menu-texture-image: url("file:///C:/Users/LASRY/.cursor/projects/c-Users-LASRY-Projects-rh2-demo/assets/c__Users_LASRY_AppData_Roaming_Cursor_User_workspaceStorage_empty-window_images_image-a7345f22-0a52-413c-9ee8-94392e87c7e3.png");
}

button, input, select, textarea { font: inherit; color: inherit; }

button {
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition), color var(--transition), transform var(--transition);
}

button:active { transform: scale(0.98); }

button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--forest-mid);
  outline-offset: 2px;
}

a { color: var(--forest-mid); }
small { font-size: 12px; color: var(--text-tertiary); }

/* Loading / empty */

.boot-message {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--s3);
  min-height: 220px;
  color: var(--text-tertiary);
  font-size: 14px;
}

.loader {
  width: 20px;
  height: 20px;
  border: 2px solid var(--border);
  border-top-color: var(--forest-mid);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

.empty-state,
.empty-cell {
  color: var(--text-tertiary);
  font-size: 14px;
  line-height: 1.55;
  text-align: center;
}

.empty-state {
  padding: var(--s6) var(--s5);
  background: var(--surface-2);
  border-radius: var(--radius-lg);
}

.empty-cell { padding: var(--s5) !important; }

.empty-inline {
  margin: 0;
  padding: var(--s4) 0;
  color: var(--text-tertiary);
  font-size: 14px;
  line-height: 1.55;
  text-align: left;
}

/* Brand */

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 16px;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.02em;
}

.brand > span {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 8px;
  background-color: transparent;
  background-image: var(--logo-image);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  color: transparent;
  font-size: 0;
  font-weight: 800;
}

/* Login */

.login-page {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 100vh;
  background: var(--login-bg);
}

.login-brand {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 100vh;
  padding: var(--s6) clamp(var(--s5), 5vw, 72px);
  background: var(--login-brand-bg);
  color: #fff;
  position: relative;
  overflow: hidden;
}

.login-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.login-bg::before {
  content: "";
  position: absolute;
  inset: -5%;
  background-image:
    linear-gradient(135deg, rgba(2, 35, 65, 0.82), rgba(2, 35, 65, 0.62)),
    var(--bg-image-login);
  background-size: cover;
  background-position: center;
  animation: slowPan 26s ease-in-out infinite alternate;
}

.login-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  opacity: 0.55;
  will-change: transform;
}

.login-blob-1 {
  width: 320px;
  height: 320px;
  top: -80px;
  right: -60px;
  background: var(--lime);
  animation: blobFloat1 14s ease-in-out infinite;
}

.login-blob-2 {
  width: 240px;
  height: 240px;
  bottom: 10%;
  left: -40px;
  background: var(--forest-mid);
  animation: blobFloat2 18s ease-in-out infinite;
}

.login-blob-3 {
  width: 180px;
  height: 180px;
  bottom: -40px;
  right: 20%;
  background: rgba(59, 123, 255, 0.35);
  animation: blobFloat3 12s ease-in-out infinite;
}

.login-brand > .brand,
.login-message {
  position: relative;
  z-index: 1;
}

.login-message h1 em {
  display: inline-block;
  font-style: normal;
  color: var(--lime);
  font-weight: 700;
  animation: textGlow 4s ease-in-out infinite;
}

.brand-large { color: #fff; }
.brand-large > span {
  background-color: transparent;
  background-image: var(--logo-image);
  background-size: cover;
  background-position: center;
  color: transparent;
}

.login-message { max-width: 420px; }

.eyebrow {
  display: block;
  margin-bottom: var(--s5);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--lime);
}

.login-message h1 {
  margin: 0;
  font-size: clamp(30px, 3.8vw, 44px);
  font-weight: 500;
  line-height: 1.12;
  letter-spacing: -0.03em;
}

.login-message > p {
  margin: var(--s4) 0 0;
  font-size: 15px;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.72);
}

.trust-row {
  display: flex;
  gap: var(--s5);
  margin-top: var(--s6);
  font-size: 12px;
  color: rgba(255, 255, 255, 0.45);
}

.trust-row span + span::before {
  content: "·";
  margin-right: var(--s5);
}

.login-panel {
  position: relative;
  display: grid;
  place-items: center;
  padding: var(--s6) var(--s5);
  background: var(--login-panel-bg);
}

.login-card { width: min(100%, 380px); animation: fadeSlideUp 0.7s cubic-bezier(0.22, 1, 0.36, 1) 0.15s both; }
.login-theme-wrap { position: absolute; top: var(--s4); right: var(--s4); }
.mobile-brand { display: none; }

.login-card h2 {
  margin: 0 0 var(--s2);
  font-size: 28px;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.03em;
}

.login-card > p {
  margin: 0 0 var(--s6);
  font-size: 14px;
  line-height: 1.55;
  color: var(--text-secondary);
}

.microsoft-button,
.demo-button {
  width: 100%;
  min-height: 48px;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 700;
}

.microsoft-button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--s3);
  border: 1px solid var(--border-strong);
  background: var(--surface);
  color: var(--text);
}

.microsoft-button:hover:not(:disabled) { background: var(--surface-hover); }
.microsoft-button:disabled { opacity: 0.45; cursor: not-allowed; }

.microsoft-logo { display: grid; grid-template-columns: repeat(2, 6px); gap: 2px; }
.microsoft-logo i {
  display: block;
  width: 6px;
  height: 6px;
  border-radius: 1px;
}
.microsoft-logo i:nth-child(1) { background: #f35325; }
.microsoft-logo i:nth-child(2) { background: #81bc06; }
.microsoft-logo i:nth-child(3) { background: #05a6f0; }
.microsoft-logo i:nth-child(4) { background: #ffba08; }

.config-note {
  margin-top: var(--s3);
  padding: var(--s3);
  border-radius: var(--radius);
  background: var(--warning-bg);
  color: var(--warning-text);
  font-size: 13px;
  line-height: 1.5;
}

.error-message {
  margin-top: var(--s3) !important;
  color: var(--error-text) !important;
  font-size: 13px;
}

.separator {
  display: flex;
  align-items: center;
  gap: var(--s3);
  margin: var(--s5) 0;
  color: var(--text-tertiary);
  font-size: 12px;
}

.separator::before,
.separator::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--border);
}

.demo-button {
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-secondary);
  font-weight: 600;
}

.demo-button:hover {
  border-color: var(--forest-mid);
  color: var(--forest);
  background: var(--lime-muted);
}

.login-card small {
  display: block;
  margin-top: var(--s5);
  font-size: 11px;
  line-height: 1.55;
  color: var(--text-tertiary);
  text-align: center;
}

/* App shell */

.app-shell {
  display: flex;
  min-height: 100vh;
  background: var(--bg);
}

.main-content {
  flex: 1;
  min-width: 0;
  min-height: 100vh;
  margin-left: var(--sidebar-width);
  position: relative;
  overflow: hidden;
}

.main-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
}

.main-bg::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--bg-image-main);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  opacity: 1;
  animation: softDrift 34s ease-in-out infinite alternate;
}

[data-theme="dark"] .main-bg::before {
  opacity: 0.85;
}

.main-bg::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.52), rgba(245, 247, 251, 0.58));
}

[data-theme="dark"] .main-bg::after {
  background: linear-gradient(160deg, rgba(11, 18, 32, 0.56), rgba(11, 18, 32, 0.64));
}

.app-shell[data-current-page="home"] .main-bg::before { background-image: var(--bg-image-main); }
.app-shell[data-current-page="pointeuse"] .main-bg::before { background-image: var(--bg-image-alt-1); }
.app-shell[data-current-page="leave"] .main-bg::before { background-image: var(--bg-image-alt-2); }
.app-shell[data-current-page="attestations"] .main-bg::before { background-image: var(--bg-image-alt-3); }
.app-shell[data-current-page="hierarchy"] .main-bg::before { background-image: var(--bg-image-card); }
.app-shell[data-current-page="admin"] .main-bg::before { background-image: var(--bg-image-main); }

[data-theme="dark"] .app-shell[data-current-page="home"] .main-bg::before { background-image: var(--bg-image-main); }
[data-theme="dark"] .app-shell[data-current-page="pointeuse"] .main-bg::before { background-image: var(--bg-image-alt-1); }
[data-theme="dark"] .app-shell[data-current-page="leave"] .main-bg::before { background-image: var(--bg-image-alt-2); }
[data-theme="dark"] .app-shell[data-current-page="attestations"] .main-bg::before { background-image: var(--bg-image-alt-3); }
[data-theme="dark"] .app-shell[data-current-page="hierarchy"] .main-bg::before { background-image: var(--bg-image-card); }
[data-theme="dark"] .app-shell[data-current-page="admin"] .main-bg::before { background-image: var(--bg-image-main); }
}

.main-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.35;
  will-change: transform;
}

.main-blob-1 {
  width: 420px;
  height: 420px;
  top: -120px;
  right: -80px;
  background: var(--lime);
  animation: blobFloat2 20s ease-in-out infinite;
}

.main-blob-2 {
  width: 300px;
  height: 300px;
  bottom: -60px;
  left: 10%;
  background: rgba(59, 123, 255, 0.22);
  animation: blobFloat1 16s ease-in-out infinite reverse;
}

.main-content .topbar,
.main-content .page {
  position: relative;
  z-index: 1;
}

/* Sidebar */

.sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  width: var(--sidebar-width);
  background: var(--sidebar-bg);
  border-right: 1px solid var(--sidebar-border);
  box-shadow: 4px 0 24px rgba(0, 0, 0, 0.12);
}

.sidebar::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(180deg, rgba(2, 35, 65, 0.88), rgba(2, 35, 65, 0.96)), var(--menu-texture-image);
  background-size: cover;
  background-position: center;
  opacity: 0.42;
}

.sidebar > * {
  position: relative;
  z-index: 1;
}

.sidebar > .brand {
  padding: 20px var(--s4) 18px;
  color: #fff;
  font-size: 15px;
  letter-spacing: -0.02em;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.sidebar > .brand > span {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 10px;
  background-color: transparent;
  background-image: var(--logo-image);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  color: transparent;
  font-size: 0;
  box-shadow: 0 4px 14px rgba(0, 70, 254, 0.22);
}

.close-menu { display: none; }

.sidebar nav {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: var(--s3) var(--s3) var(--s4);
  overflow-y: auto;
}

.sidebar nav button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 11px 14px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--sidebar-text);
  font-size: 13px;
  font-weight: 600;
  text-align: left;
  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.sidebar nav button:hover {
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.08);
  color: var(--sidebar-text-active);
}

.sidebar nav button.active {
  background: rgba(59, 123, 255, 0.16);
  border-color: rgba(59, 123, 255, 0.32);
  color: #fff;
  box-shadow: inset 3px 0 0 var(--forest-mid);
}

.sidebar .nav-badge {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: var(--radius-pill);
  background: rgba(59, 123, 255, 0.22);
  border: 1px solid rgba(59, 123, 255, 0.35);
  color: #cfe0ff;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.sidebar-bottom {
  padding: var(--s3) var(--s3) var(--s4);
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.sidebar .user-card {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  grid-template-areas:
    "avatar text"
    "action action";
  gap: 6px 10px;
  padding: 10px 10px 9px;
  border-radius: 14px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.09) 0%, rgba(255, 255, 255, 0.03) 100%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.07),
    0 8px 20px rgba(0, 0, 0, 0.08);
}

.sidebar .avatar-sidebar-user {
  grid-area: avatar;
  align-self: start;
}

.sidebar .user-card-text {
  grid-area: text;
  min-width: 0;
  overflow: hidden;
}

.sidebar .user-card strong {
  display: block;
  font-size: 12px;
  font-weight: 700;
  color: #fff;
  line-height: 1.25;
  letter-spacing: -0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar .user-card-email {
  display: block;
  margin-top: 2px;
  font-size: 10px;
  color: rgba(255, 255, 255, 0.55);
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar .logout-btn {
  grid-area: action;
  width: 100%;
  margin-top: 1px;
  padding: 5px 8px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.74);
  font-size: 10px;
  font-weight: 600;
  text-align: center;
  white-space: nowrap;
  transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.sidebar .logout-btn:hover {
  color: #fecaca;
  border-color: rgba(248, 113, 113, 0.35);
  background: rgba(248, 113, 113, 0.12);
}

.app-shell.is-animating .sidebar {
  perspective: 1200px;
}

.app-shell.is-animating .sidebar > .brand {
  animation: welcomeCardIn 0.75s cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: left center;
}

.app-shell.is-animating .sidebar > .brand > span {
  animation: welcomeLogoPop 0.65s cubic-bezier(0.34, 1.56, 0.64, 1) 0.12s both;
}

.app-shell.is-animating .sidebar nav button {
  animation: humanaPanel3DIn 0.65s cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: left center;
}

.app-shell.is-animating .sidebar nav button:nth-child(1) { animation-delay: 0.08s; }
.app-shell.is-animating .sidebar nav button:nth-child(2) { animation-delay: 0.12s; }
.app-shell.is-animating .sidebar nav button:nth-child(3) { animation-delay: 0.16s; }
.app-shell.is-animating .sidebar nav button:nth-child(4) { animation-delay: 0.2s; }
.app-shell.is-animating .sidebar nav button:nth-child(5) { animation-delay: 0.24s; }
.app-shell.is-animating .sidebar nav button:nth-child(6) { animation-delay: 0.28s; }
.app-shell.is-animating .sidebar nav button:nth-child(7) { animation-delay: 0.32s; }

.app-shell.is-animating .sidebar-bottom {
  animation: humanaPanel3DIn 0.7s cubic-bezier(0.22, 1, 0.36, 1) 0.34s both;
  transform-origin: left bottom;
}

/* Avatar */

.avatar {
  display: inline-grid;
  width: 38px;
  min-width: 38px;
  height: 38px;
  place-items: center;
  border-radius: var(--radius);
  font-size: 12px;
  font-weight: 700;
  color: var(--forest);
  background: var(--lime);
}

.avatar.violet { color: var(--forest); background: var(--lime); }
.avatar.blue { color: #1e3a5f; background: #bfdbfe; }
.avatar.orange { color: #7c2d12; background: #fed7aa; }
.avatar.green { color: var(--forest); background: #bbf7d0; }
.avatar.pink { color: #831843; background: #fbcfe8; }

.avatar-user-photo {
  color: transparent;
  font-size: 0;
  background-color: transparent;
  background-image: var(--logo-image);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  border: none;
  width: 44px;
  min-width: 44px;
  height: 44px;
  border-radius: 10px;
}

.sidebar .avatar.avatar-sidebar-user {
  display: inline-grid;
  place-items: center;
  width: 38px;
  min-width: 38px;
  height: 38px;
  border-radius: 50%;
  background: linear-gradient(145deg, var(--forest-mid), #3b7bff);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.02em;
  line-height: 1;
  box-shadow: 0 0 0 2px rgba(159, 190, 255, 0.28);
}

.sidebar .admin-pill {
  display: inline-block;
  margin-top: 4px;
  padding: 2px 7px;
  border-radius: var(--radius-pill);
  background: rgba(59, 123, 255, 0.2);
  border: 1px solid rgba(59, 123, 255, 0.3);
  color: #cfe0ff;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Topbar */

.topbar {
  display: flex;
  align-items: center;
  gap: var(--s4);
  height: var(--header-height);
  padding: 0 var(--s5);
  background: var(--topbar-bg);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
}

.topbar-page {
  font-size: 20px;
  font-weight: 700;
  color: var(--text);
  letter-spacing: -0.03em;
}

.topbar-page.is-animating {
  animation: humanaPanel3DIn 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;
  transform-origin: left center;
}

.page-heading.is-animating {
  animation: humanaPanel3DIn 0.55s cubic-bezier(0.22, 1, 0.36, 1) 0.05s both;
  transform-origin: left center;
}

.app-shell[data-current-page="home"] .topbar-page { visibility: hidden; }

.topbar-actions {
  display: flex;
  align-items: center;
  gap: var(--s3);
  margin-left: auto;
}

.menu-button { display: none; }

.demo-pill {
  padding: 5px 12px;
  border-radius: var(--radius-pill);
  background: var(--lime-muted);
  color: var(--forest);
  font-size: 11px;
  font-weight: 700;
}

/* Page */

.page {
  max-width: 1100px;
  margin: 0 auto;
  padding: var(--s5) var(--s5) var(--s7);
}

.page-content {
  position: relative;
}

.page-heading { margin-bottom: var(--s5); }

.page-heading p {
  margin: 0;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.app-shell[data-current-page="home"] .page-heading { display: none; }
.page-spacer { margin-top: var(--s5); }

/* Buttons */

.primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  padding: 0 var(--s5);
  border: none;
  border-radius: var(--radius);
  background: var(--lime);
  color: var(--forest);
  font-size: 14px;
  font-weight: 800;
  position: relative;
  overflow: hidden;
}

.primary::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg, transparent 35%, rgba(255, 255, 255, 0.45) 50%, transparent 65%);
  transform: translateX(-120%);
  transition: transform 0.55s ease;
}

.primary:hover::after { transform: translateX(120%); }
.primary:hover { background: var(--lime-hover); }

.outline-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 38px;
  padding: 0 var(--s4);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text);
  font-size: 13px;
  font-weight: 600;
}

.outline-button:hover {
  border-color: var(--forest-mid);
  background: var(--lime-muted);
  color: var(--forest);
}

.admin-form-actions,
.admin-row-actions {
  display: flex;
  gap: var(--s2);
  flex-wrap: wrap;
}

.admin-row-actions .outline-button { width: auto; }
.error-card .primary { margin-top: var(--s4); }

/* Cards */

.card,
.stat-card,
.document-card,
.hours-card,
.balance-card {
  border: none;
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.card:hover,
.stat-card:hover,
.hours-card:hover,
.balance-card:hover,
.home-widget:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(2, 35, 65, 0.12);
}

.card { padding: var(--s5); }

.card-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--s3);
  margin-bottom: var(--s4);
  padding-bottom: var(--s3);
  border-bottom: 1px solid var(--border);
}

.card-heading h3 {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
}

.card-heading button,
.home-link {
  border: none;
  background: none;
  padding: 0;
  color: var(--forest-mid);
  font-size: 13px;
  font-weight: 700;
}

.home-link:hover,
.card-heading button:hover { text-decoration: underline; }

/* Section cards */

.hierarchy-grid .card,
.page-spacer.card,
.home-widget {
  padding: 0;
  overflow: hidden;
}

.home-widget:nth-child(3),
.home-widget:nth-child(4) {
  background-image: linear-gradient(rgba(255, 255, 255, 0.94), rgba(255, 255, 255, 0.94)), var(--bg-image-card);
  background-size: cover;
  background-position: center;
}

[data-theme="dark"] .home-widget:nth-child(3),
[data-theme="dark"] .home-widget:nth-child(4) {
  background-image: linear-gradient(rgba(18, 28, 47, 0.92), rgba(18, 28, 47, 0.92)), var(--bg-image-card);
}

.hierarchy-grid .card > :not(.card-heading),
.page-spacer.card > :not(.card-heading),
.home-widget > :not(.card-heading) {
  padding-left: var(--s5);
  padding-right: var(--s5);
}

.hierarchy-grid .card > :last-child:not(.card-heading),
.page-spacer.card > :last-child:not(.card-heading),
.home-widget > :last-child:not(.card-heading) {
  padding-bottom: var(--s5);
}

.hierarchy-grid .card > .card-heading,
.page-spacer.card > .card-heading,
.home-widget > .card-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0;
  padding: var(--s4) var(--s5);
  border-bottom: 1px solid var(--border);
  background: var(--surface-2);
}

.hierarchy-grid .card > .card-heading h3,
.page-spacer.card > .card-heading h3,
.home-widget > .card-heading h3 {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-tertiary);
}

.hierarchy-grid .card > .card-heading + *,
.page-spacer.card > .card-heading + *,
.home-widget > .card-heading + * {
  padding-top: var(--s4);
}

/* Stats */

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--s3);
}

.stat-card {
  display: grid;
  padding: var(--s4);
  grid-template-columns: 40px 1fr;
  column-gap: var(--s3);
}

.stat-icon {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border-radius: var(--radius);
  font-size: 16px;
  grid-row: span 2;
  background: var(--lime-muted);
  color: var(--forest);
}

.stat-icon.purple, .job-icon.purple { color: var(--forest); background: var(--lime-muted); }
.stat-icon.orange, .job-icon.orange { color: #7c2d12; background: #ffedd5; }
.stat-icon.blue, .job-icon.blue { color: #1e3a5f; background: #dbeafe; }
.stat-icon.green, .job-icon.green { color: var(--forest); background: #dcfce7; }

.stat-card > span {
  align-self: end;
  font-size: 12px;
  color: var(--text-tertiary);
}

.stat-card > strong {
  font-size: 24px;
  font-weight: 800;
  color: var(--text);
  letter-spacing: -0.03em;
}

.stat-card small {
  grid-column: 1 / -1;
  margin-top: var(--s2);
  font-size: 11px;
  color: var(--success-text);
}

/* Tables */

.table-card { padding: 0; overflow: hidden; }

.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--s3) var(--s4);
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}

.toolbar h3 {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
}

.table-wrap { overflow-x: auto; }

table { width: 100%; border-collapse: collapse; }

th {
  padding: 10px var(--s4);
  text-align: left;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  background: var(--table-head);
  border-bottom: 1px solid var(--border);
}

td {
  padding: 13px var(--s4);
  font-size: 14px;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}

tbody tr:last-child td { border-bottom: none; }
tbody tr:hover td { background: var(--surface-2); }

.person strong { color: var(--text); font-weight: 700; }
.person span { font-size: 12px; color: var(--text-tertiary); }

/* Badges */

.badge {
  display: inline-flex;
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.5;
}

.badge.success { background: var(--lime-muted); color: var(--forest); }
.badge.warning { background: var(--warning-bg); color: var(--warning-text); }
.badge.neutral { background: var(--surface-2); color: var(--text-tertiary); }

/* Tabs */

.tabs {
  display: flex;
  gap: var(--s2);
  margin-bottom: var(--s4);
}

.tabs button {
  padding: var(--s2) var(--s4);
  border: none;
  border-radius: var(--radius-pill);
  background: var(--surface-2);
  color: var(--text-tertiary);
  font-size: 13px;
  font-weight: 600;
}

.tabs button.active {
  background: var(--forest-mid);
  color: #fff;
  font-weight: 700;
}

/* Pointeuse */

.clock-grid,
.feature-grid,
.hierarchy-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--s4);
}

.hours-grid,
.balance-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--s3);
}

.leave-calendar-card {
  padding: 0;
  overflow: hidden;
}

.leave-cal-heading {
  flex-wrap: wrap;
  gap: var(--s3);
}

.leave-cal-nav {
  display: flex;
  align-items: center;
  gap: var(--s2);
}

.leave-cal-month {
  min-width: 9rem;
  text-align: center;
  text-transform: capitalize;
  font-size: 14px;
}

.leave-cal-note {
  margin: 0;
  padding: var(--s3) var(--s5) 0;
  font-size: 13px;
  color: var(--text-muted);
}

.leave-cal-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 1px;
  margin: var(--s4) var(--s5) var(--s3);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--border);
}

.leave-cal-weekday,
.leave-cal-cell {
  min-height: 88px;
  background: var(--surface);
}

.leave-cal-weekday {
  min-height: auto;
  padding: var(--s2);
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  background: var(--surface-2);
}

.leave-cal-cell {
  display: flex;
  flex-direction: column;
  gap: var(--s1);
  padding: var(--s2);
}

.leave-cal-cell--empty {
  background: color-mix(in srgb, var(--surface-2) 70%, var(--surface));
}

.leave-cal-cell.is-weekend {
  background: color-mix(in srgb, var(--surface-2) 55%, var(--surface));
}

.leave-cal-cell.is-today .leave-cal-day {
  background: var(--forest-mid);
  color: #fff;
}

.leave-cal-cell.has-conflict {
  box-shadow: inset 0 0 0 2px color-mix(in srgb, #d97706 70%, transparent);
  background: color-mix(in srgb, #d97706 10%, var(--surface));
}

.leave-cal-day {
  align-self: flex-end;
  width: 1.6rem;
  height: 1.6rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.leave-cal-events {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-height: 0;
}

.leave-cal-event {
  display: block;
  padding: 2px 4px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #fff;
}

.leave-cal-event.leave-type-cp { background: #2f6f4f; }
.leave-cal-event.leave-type-rtt { background: #2563eb; }
.leave-cal-event.leave-type-sick { background: #b45309; }
.leave-cal-event.leave-type-unpaid { background: #6b7280; }

.leave-cal-event.is-pending {
  background-image: repeating-linear-gradient(
    -45deg,
    transparent,
    transparent 4px,
    rgba(255, 255, 255, 0.22) 4px,
    rgba(255, 255, 255, 0.22) 8px
  );
}

.leave-cal-more {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
}

.leave-cal-legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--s3);
  padding: 0 var(--s5) var(--s5);
}

.leave-cal-legend-item {
  display: inline-flex;
  align-items: center;
  gap: var(--s2);
  font-size: 12px;
  color: var(--text-muted);
}

.leave-cal-legend-item i {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  display: inline-block;
}

.leave-cal-legend-item .leave-type-cp { background: #2f6f4f; }
.leave-cal-legend-item .leave-type-rtt { background: #2563eb; }
.leave-cal-legend-item .leave-type-sick { background: #b45309; }

.leave-cal-legend-pending i {
  background: #2f6f4f;
  background-image: repeating-linear-gradient(
    -45deg,
    transparent,
    transparent 2px,
    rgba(255, 255, 255, 0.35) 2px,
    rgba(255, 255, 255, 0.35) 4px
  );
}

.leave-cal-legend-conflict i {
  background: color-mix(in srgb, #d97706 35%, var(--surface));
  box-shadow: inset 0 0 0 2px #d97706;
}

.hours-card,
.balance-card { padding: var(--s4) var(--s5); }

.hours-label {
  display: block;
  margin-bottom: var(--s2);
  font-size: 12px;
  font-weight: 600;
  color: var(--text-tertiary);
}

.hours-card strong {
  font-size: 28px;
  font-weight: 800;
  color: var(--text);
  letter-spacing: -0.04em;
}

.clock-status {
  display: flex;
  align-items: flex-start;
  gap: var(--s3);
  padding: var(--s3) var(--s4);
  margin-bottom: var(--s4);
  border-radius: var(--radius-lg);
  background: var(--surface-2);
  border: 1px solid var(--border);
}

.clock-status-dot {
  width: 11px;
  height: 11px;
  margin-top: 5px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--text-tertiary);
}

.clock-status-body {
  min-width: 0;
  flex: 1;
}

.clock-status.in {
  background: linear-gradient(135deg, rgba(0, 70, 254, 0.1), rgba(207, 224, 255, 0.42));
  border-color: rgba(0, 70, 254, 0.28);
  animation: statusPulse 2.5s ease-in-out infinite;
}

.clock-status.in .clock-status-dot {
  background: #16a34a;
  box-shadow: 0 0 0 4px rgba(22, 163, 74, 0.22);
  animation: statusDotPulse 2s ease-in-out infinite;
}

.clock-status.in strong {
  color: #022341;
}

.clock-status.in span {
  color: #1e3a5f;
}

.clock-status.done {
  background: linear-gradient(135deg, rgba(0, 70, 254, 0.08), rgba(207, 224, 255, 0.16));
  border: 1px solid rgba(0, 70, 254, 0.14);
}

.clock-status.done .clock-status-dot {
  background: var(--forest-mid);
  box-shadow: 0 0 0 4px rgba(0, 70, 254, 0.14);
}

.clock-status.out {
  background: var(--surface-2);
}

.clock-status.out .clock-status-dot {
  background: var(--text-tertiary);
}

.clock-status.break {
  background: linear-gradient(135deg, rgba(245, 158, 11, 0.14), rgba(254, 243, 199, 0.42));
  border: 1px solid rgba(245, 158, 11, 0.28);
}

.clock-status.break .clock-status-dot {
  background: #f59e0b;
  box-shadow: 0 0 0 4px rgba(245, 158, 11, 0.22);
  animation: statusDotPulse 2s ease-in-out infinite;
}

.clock-status.break strong {
  color: #92400e;
}

.clock-status.break span {
  color: #b45309;
}

.clock-actions {
  display: grid;
  gap: var(--s3);
}

.clock-button.break-start {
  border: none;
  background: linear-gradient(145deg, #fbbf24, #f59e0b);
  color: #78350f;
}

.clock-button.break-start:hover {
  background: linear-gradient(145deg, #f59e0b, #d97706);
}

.clock-button.break-end {
  border: none;
  background: linear-gradient(145deg, #34d399, #10b981);
  color: #064e3b;
}

.clock-button.break-end:hover {
  background: linear-gradient(145deg, #10b981, #059669);
}

.clock-button-secondary {
  background: var(--surface-2);
  color: var(--forest-mid);
  border: 1px solid rgba(0, 70, 254, 0.2);
}

.clock-button-secondary:hover {
  background: var(--lime-muted);
}

.clock-status strong {
  display: block;
  margin-bottom: var(--s1);
  font-size: 17px;
  font-weight: 700;
  color: var(--text);
}

.clock-status span {
  display: block;
  font-size: 13px;
  line-height: 1.45;
  color: var(--text-secondary);
}

.clock-button {
  width: 100%;
  min-height: 46px;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 800;
}

.clock-button.in {
  border: none;
  background: var(--lime);
  color: var(--forest);
}

.clock-button.in:hover { background: var(--lime-hover); }

.clock-button.out {
  border: none;
  background: var(--forest-mid);
  color: #fff;
}

.clock-button.out:hover { background: var(--forest); }

.clock-hint {
  margin-top: var(--s3);
  font-size: 12px;
  color: var(--text-tertiary);
}

.punch-list { display: grid; gap: var(--s2); }

.punch-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--s3);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.punch-type {
  padding: 3px 10px;
  border-radius: var(--radius-pill);
  font-size: 11px;
  font-weight: 700;
}

.punch-type.in { background: var(--lime-muted); color: var(--forest); }
.punch-type.out { background: var(--surface); color: var(--text-secondary); }
.punch-type.break_start { background: rgba(245, 158, 11, 0.16); color: #b45309; }
.punch-type.break_end { background: rgba(16, 185, 129, 0.16); color: #047857; }

/* Balances */

.balance-head {
  display: flex;
  justify-content: space-between;
  margin-bottom: var(--s2);
}

.balance-head strong {
  font-size: 13px;
  font-weight: 700;
  color: var(--text);
}

.balance-head span {
  font-size: 12px;
  color: var(--text-tertiary);
}

.balance-track {
  height: 6px;
  border-radius: var(--radius-pill);
  background: var(--border);
  overflow: hidden;
}

.balance-track i {
  display: block;
  height: 100%;
  background: var(--forest-mid);
  border-radius: inherit;
  transition: width 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}

.balance-meta {
