}

.org-children > .org-branch::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 2px;
  height: 28px;
  background: linear-gradient(180deg, rgba(0, 70, 254, 0.45), var(--forest-mid));
