.org-card small {
  display: block;
  margin-top: 2px;
  font-size: 11px;
  color: var(--text-tertiary);
}

.hierarchy-org-card .org-expand {
  margin-top: var(--s3);
  padding: 5px 12px 5px 7px;
  border-color: rgba(0, 70, 254, 0.24);
