  box-shadow: 0 2px 8px rgba(0, 70, 254, 0.1);
}

.hierarchy-org-card .org-team-count {
  min-width: 22px;
  height: 22px;
  background: linear-gradient(145deg, var(--forest-mid), #3b7bff);
}

.hierarchy-org-card .hierarchy-result-count {
  background: linear-gradient(135deg, rgba(0, 70, 254, 0.12), rgba(207, 224, 255, 0.45));
